export function adminStaffPage(api: string) {
  const body = `<div class="shell"><aside class="side">${adminNavigation("/admin/users")}</aside><main><a href="/admin/users">← Người dùng</a><div class="top"><div><h1>Nhân sự & phân quyền</h1><p class="muted">Vai trò quản trị độc lập hoàn toàn với cấp khách hàng.</p></div></div><form id="createForm" class="card mutation-grid"><label>Email<input name="email" type="email" required></label><label>Tên đăng nhập<input name="username" minlength="3" required></label><label>Vai trò<select name="role"><option value="STAFF">Nhân viên</option><option value="ADMIN">Quản trị viên</option></select></label><button>Tạo tài khoản và liên kết đặt lại mật khẩu</button></form><section id="staffRows" class="card recent"></section><div id="message" class="error"></div></main></div>`;
  const script = `${client(api)};let state;const esc=v=>{const d=document.createElement('div');d.textContent=String(v??'');return d.innerHTML};async function load(){state=await call('/api/v1/admin/staff');staffRows.innerHTML=state.items.map(user=>'<article class="notice"><div><b>'+esc(user.username)+'</b> · '+esc(user.email)+'<p>'+user.roles.join(', ')+' · '+user.status+' · đăng nhập cuối '+(user.lastLoginAt?new Date(user.lastLoginAt).toLocaleString('vi-VN'):'Chưa có')+'</p></div><button style="width:auto;margin:0" data-staff="'+user.id+'">Phân quyền</button></article>').join('')||'<p class="empty">Chưa có nhân sự.</p>';document.querySelectorAll('[data-staff]').forEach(button=>button.onclick=()=>edit(button.dataset.staff))}async function edit(id){const user=state.items.find(row=>row.id===id);if(user.roles.includes('SUPER_ADMIN')){message.textContent='Không thể sửa Super Admin tại đây.';return}const selected=prompt('Nhập permission, cách nhau bằng dấu phẩy',state.permissions.map(p=>p.code).filter(code=>code.endsWith('.view')).join(','));if(selected===null)return;const role=prompt('Vai trò STAFF hoặc ADMIN',user.roles.includes('ADMIN')?'ADMIN':'STAFF');if(!confirm('Xác nhận cập nhật quyền nhân sự?'))return;await call('/api/v1/admin/staff/'+id,{method:'POST',body:JSON.stringify({role,permissions:selected.split(',').map(x=>x.trim()).filter(Boolean),status:user.status})});message.textContent='Đã cập nhật quyền.';load()}createForm.onsubmit=async e=>{e.preventDefault();const result=await call('/api/v1/admin/staff',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(createForm)))});message.textContent=result.resetToken?'Token đặt lại (chỉ development): '+result.resetToken:'Đã tạo nhân sự và gửi quy trình đặt lại mật khẩu.';createForm.reset();load()};load().catch(e=>message.textContent=e.message)`;
  return layout("Nhân sự", body, script);
}

export function adminSettingsPage(api: string) {
  const body = `<div class="shell"><aside class="side">${adminNavigation("/admin/settings")}</aside><main><div class="top"><div><h1>Trung tâm cài đặt</h1><p class="muted">Cấu hình website, giao diện, dịch vụ và kênh hỗ trợ.</p></div></div><div class="tabs recent"><button class="chip selected" data-tab="general">Chung</button><button class="chip" data-tab="theme">Giao diện</button><button class="chip" data-tab="service">Dịch vụ</button><button class="chip" data-tab="support">Hỗ trợ</button><button class="chip" data-tab="security">Bảo mật</button><button class="chip" data-tab="modules">Module</button></div><form id="settingsForm" class="card recent"><section data-panel="general"><h2>Thông tin chung</h2><label>Tiêu đề website<input name="siteName"></label><label>Mô tả meta<textarea name="metaDescription"></textarea></label><label>Từ khóa meta<input name="metaKeywords"></label><label>Ngôn ngữ mặc định<select name="defaultLanguage"><option value="vi">Tiếng Việt</option><option value="en">English</option></select></label><label>Tiền tệ<input name="currency" maxlength="10"></label><label>Múi giờ<input name="timezone"></label><label>Thông báo<textarea name="announcement"></textarea></label><label><input name="maintenanceMode" type="checkbox"> Bật chế độ bảo trì</label><label>Nội dung bảo trì<textarea name="maintenanceMessage"></textarea></label></section><section data-panel="theme" hidden><h2>Giao diện</h2><p>Người dùng có thể chọn Sáng, Tối hoặc Hệ thống bằng nút ◐ trên thanh điều hướng.</p><div class="cards"><article class="card">Sáng<br><small>Nền xám nhẹ, thẻ trắng, màu xanh chủ đạo.</small></article><article class="card">Tối<br><small>Tương phản cao cho bảng, form và modal.</small></article><article class="card">Hệ thống<br><small>Tự động theo thiết bị.</small></article></div></section><section data-panel="service" hidden><h2>Chính sách dịch vụ</h2><label><input name="serviceSalesEnabled" type="checkbox"> Cho phép bán dịch vụ</label><label>Đơn trùng<select name="duplicateOrderPolicy"><option value="ALLOW">Cho phép</option><option value="WARN">Cảnh báo</option><option value="BLOCK">Chặn</option></select></label></section><section data-panel="support" hidden><h2>Kênh hỗ trợ</h2>${["Facebook", "Telegram", "Whatsapp", "Email", "Phone"].map((channel) => `<label class="toggle"><input name="support${channel}Enabled" type="checkbox"> Bật ${channel}</label><label>Giá trị / liên kết ${channel}<input name="support${channel}"></label>`).join("")}</section><section data-panel="security" hidden><h2>Bảo mật</h2><p>Quản lý phiên đăng nhập, đặt lại mật khẩu an toàn và phân quyền tại màn hình Người dùng / Nhân sự.</p><a href="/admin/users">Mở Người dùng & nhân sự →</a></section><section data-panel="modules" hidden><h2>Module đang hoạt động</h2><div class="cards"><article class="card"><b>Cấp khách hàng</b><p>Đang sử dụng</p></article><article class="card"><b>Giới thiệu</b><p>Đang sử dụng</p></article><article class="card"><b>Mã giảm giá</b><p>Đang sử dụng</p></article><article class="card"><b>SMTP</b><p>Cấu hình bằng biến môi trường bảo mật.</p></article></div></section><button id="saveSettings">Lưu cài đặt</button></form><div id="message" class="error"></div></main></div>`;
  const script = `${client(api)};document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('selected',x===button));document.querySelectorAll('[data-panel]').forEach(x=>x.hidden=x.dataset.panel!==button.dataset.tab)});async function load(){const rows=await call('/api/v1/admin/settings'),values=Object.fromEntries(rows.filter(x=>x.group==='general').map(x=>[x.key,x.value]));for(const element of settingsForm.elements){if(!element.name)continue;if(element.type==='checkbox')element.checked=values[element.name]===true;else if(values[element.name]!=null)element.value=values[element.name]}}settingsForm.onsubmit=async e=>{e.preventDefault();saveSettings.disabled=true;const body={};for(const element of settingsForm.elements){if(!element.name)continue;body[element.name]=element.type==='checkbox'?element.checked:element.value}try{await call('/api/v1/admin/settings',{method:'POST',body:JSON.stringify(body)});message.textContent='Đã lưu cài đặt.'}catch(error){message.textContent=error.message}finally{saveSettings.disabled=false}};load().catch(e=>message.textContent=e.message)`;
  return layout("Cài đặt", body, script);
}

export function adminPricingPage(api: string) {
  const body = `<div class="shell"><aside class="side">${adminNavigation("/admin/pricing")}</aside><main><div class="top"><div><h1>Bảng giá</h1><p class="muted">Chọn phạm vi và đặt phần trăm lợi nhuận cho ba cấp khách hàng.</p></div><span id="alertCount" class="pill">0 cảnh báo</span></div><form id="simplePricing" class="card"><div class="mutation-grid"><label>Nhà cung cấp<select name="providerId" id="pricingProvider"><option value="">Tất cả</option></select></label><label>Nền tảng<select name="platformId" id="pricingPlatform"><option value="">Tất cả</option></select></label><label>Danh mục<select name="categoryId" id="pricingCategory"><option value="">Tất cả</option></select></label><label>Dịch vụ cụ thể<select multiple name="serviceIds" id="pricingServices"></select><small id="pricingScopeHelp">Không chọn nghĩa là áp dụng toàn bộ phạm vi.</small></label></div><div class="cards recent"><article class="card"><h3>Khách hàng</h3><label>Lợi nhuận:<div class="input-action"><input name="KHACH_LE" value="30" inputmode="decimal" required><span>%</span></div></label></article><article class="card"><h3>Đại lý</h3><label>Lợi nhuận:<div class="input-action"><input name="CTV" value="25" inputmode="decimal" required><span>%</span></div></label></article><article class="card"><h3>NPP</h3><label>Lợi nhuận:<div class="input-action"><input name="DAI_LY" value="20" inputmode="decimal" required><span>%</span></div></label></article></div><div class="tabs"><button id="pricingPreview" type="button">Xem trước</button><button id="pricingApply" type="button" disabled>Áp dụng</button></div></form><section class="card recent"><div class="section-title"><h2>Xem trước</h2><span id="affectedCount" class="pill">0 dịch vụ</span></div><div class="table-wrap"><table><thead><tr><th>Dịch vụ</th><th>Giá NCC</th><th>Giá Khách hàng</th><th>Giá Đại lý</th><th>Giá NPP</th><th>Cảnh báo</th></tr></thead><tbody id="pricingRows"><tr><td colspan="6" class="empty">Chọn phạm vi rồi nhấn Xem trước.</td></tr></tbody></table></div></section><details class="card recent"><summary><b>Cài đặt nâng cao</b></summary><p>Professional Pricing engine, minimum-profit floor, PriceRule, lịch sử giá và cảnh báo vẫn hoạt động ở backend.</p><div id="pricingAlerts"></div><h3>Lịch sử giá gần đây</h3><div id="pricingHistory"></div></details><div id="message" class="error"></div></main></div>`;
  const script = `${client(api)};let state,previewSignature='';const esc=v=>{const d=document.createElement('div');d.textContent=String(v??'');return d.innerHTML},compactMoney=v=>{const text=String(v??'0');return text.includes('.')?text.replace(/0+$/,'').replace(/\.$/,''):text};function mappedServiceIds(providerId){if(!providerId)return null;const providerServiceIds=new Set(state.providerServices.filter(x=>x.providerId===providerId&&x.active!==false&&x.stale!==true).map(x=>x.id));return new Set(state.mappings.filter(x=>x.active&&providerServiceIds.has(x.providerServiceId)).map(x=>x.serviceId))}function scopedServices(){const mapped=mappedServiceIds(pricingProvider.value);return state.services.filter(service=>(!mapped||mapped.has(service.id))&&(!pricingPlatform.value||state.categories.some(c=>c.id===service.categoryId&&c.platformId===pricingPlatform.value))&&(!pricingCategory.value||service.categoryId===pricingCategory.value))}function setOptions(select,items,current){select.innerHTML='<option value="">Tất cả</option>'+items.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('');select.value=items.some(x=>x.id===current)?current:''}function rebuildPlatforms(){const current=pricingPlatform.value,mapped=mappedServiceIds(pricingProvider.value),categoryIds=new Set(state.services.filter(s=>!mapped||mapped.has(s.id)).map(s=>s.categoryId)),platformIds=new Set(state.categories.filter(c=>categoryIds.has(c.id)).map(c=>c.platformId));setOptions(pricingPlatform,state.platforms.filter(p=>platformIds.has(p.id)),current)}function rebuildCategories(){const current=pricingCategory.value,mapped=mappedServiceIds(pricingProvider.value),categoryIds=new Set(state.services.filter(s=>!mapped||mapped.has(s.id)).map(s=>s.categoryId));setOptions(pricingCategory,state.categories.filter(c=>categoryIds.has(c.id)&&(!pricingPlatform.value||c.platformId===pricingPlatform.value)),current)}function rebuildServices(){const items=scopedServices();pricingServices.innerHTML=items.length?items.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join(''):'<option disabled>Không có dịch vụ phù hợp bộ lọc</option>';pricingScopeHelp.textContent=items.length?'Không chọn nghĩa là áp dụng toàn bộ '+items.length+' dịch vụ trong phạm vi.':'Không có dịch vụ phù hợp bộ lọc';pricingPreview.disabled=!items.length;if(!items.length)pricingRows.innerHTML='<tr><td colspan="6" class="empty">Không có dịch vụ phù hợp bộ lọc</td></tr>'}function cascade(level){if(level==='provider'){pricingPlatform.value='';pricingCategory.value='';rebuildPlatforms()}if(level==='provider'||level==='platform'){pricingCategory.value='';rebuildCategories()}rebuildServices();invalidate()}function payload(){const form=Object.fromEntries(new FormData(simplePricing)),serviceIds=[...pricingServices.selectedOptions].map(x=>x.value),body={tiers:{KHACH_LE:form.KHACH_LE,CTV:form.CTV,DAI_LY:form.DAI_LY}};if(form.providerId)body.providerId=form.providerId;if(form.platformId)body.platformId=form.platformId;if(form.categoryId)body.categoryId=form.categoryId;if(serviceIds.length)body.serviceIds=serviceIds;return body}async function load(){const [pricing,alerts]=await Promise.all([call('/api/v1/admin/pricing'),call('/api/v1/admin/pricing/alerts')]);state=pricing;pricingProvider.innerHTML='<option value="">Tất cả</option>'+state.providers.filter(x=>x.status==='ACTIVE').map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('');rebuildPlatforms();rebuildCategories();rebuildServices();for(const code of ['KHACH_LE','CTV','DAI_LY']){const group=state.priceGroups.find(x=>x.code===code);if(group)simplePricing.elements[code].value=compactMoney(group.defaultMarkupPercent)}alertCount.textContent=alerts.open+' cảnh báo';pricingAlerts.innerHTML=alerts.items.slice(0,10).map(x=>'<p><b>'+esc(x.title)+'</b> · '+esc(x.message)+'</p>').join('')||'<p class="empty">Không có cảnh báo.</p>';pricingHistory.innerHTML=state.priceHistory.slice(0,20).map(x=>'<p>'+new Date(x.createdAt).toLocaleString('vi-VN')+' · '+compactMoney(x.oldSaleRate)+' → '+compactMoney(x.newSaleRate)+'</p>').join('')||'<p class="empty">Chưa có lịch sử.</p>'}function invalidate(){previewSignature='';pricingApply.disabled=true}pricingProvider.onchange=()=>cascade('provider');pricingPlatform.onchange=()=>cascade('platform');pricingCategory.onchange=()=>cascade('category');pricingServices.onchange=invalidate;simplePricing.querySelectorAll('input').forEach(x=>x.oninput=invalidate);pricingPreview.onclick=async()=>{pricingPreview.disabled=true;message.textContent='Đang tính giá…';try{const body=payload(),result=await call('/api/v1/admin/pricing/simple/preview',{method:'POST',body:JSON.stringify(body)});previewSignature=JSON.stringify(body);affectedCount.textContent=result.count+' dịch vụ';pricingRows.innerHTML=result.items.length?result.items.map(x=>'<tr><td>'+esc(x.service)+'</td><td>'+compactMoney(x.providerCost)+'</td><td>'+compactMoney(x.prices.KHACH_LE)+'</td><td>'+compactMoney(x.prices.CTV)+'</td><td>'+compactMoney(x.prices.DAI_LY)+'</td><td>'+(x.warnings.length?'<span class="negative">Giá bán thấp hơn mức an toàn; backend áp dụng safety floor.</span>':'—')+'</td></tr>').join(''):'<tr><td colspan="6" class="empty">Không có dịch vụ phù hợp bộ lọc</td></tr>';pricingApply.disabled=!result.count;message.textContent=result.count?'Đã xem trước '+result.count+' dịch vụ.':'Không có dịch vụ phù hợp bộ lọc'}catch(e){message.textContent=e.message||'Không thể xem trước giá.'}finally{pricingPreview.disabled=!scopedServices().length}};pricingApply.onclick=async()=>{const body=payload();if(JSON.stringify(body)!==previewSignature){message.textContent='Phạm vi hoặc tỷ lệ đã thay đổi. Hãy xem trước lại.';invalidate();return}if(!confirm('Áp dụng giá cho cả ba cấp khách hàng?'))return;pricingApply.disabled=true;try{const result=await call('/api/v1/admin/pricing/simple/apply',{method:'POST',body:JSON.stringify(body)});message.textContent='Đã cập nhật '+result.applied+' dịch vụ trong một giao dịch.';previewSignature='';await load()}catch(e){message.textContent=e.message||'Không thể áp dụng bảng giá.'}};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load().catch(e=>message.textContent=e.message||'Không thể tải bảng giá.')`;
  return layout("Bảng giá", body, script);
}
